        address resolver,
        bytes memory name,
        bytes memory data,
        bool hasContext,
        bytes memory context,
        string[] memory batchGateways
    ) public view returns (bytes memory) {
        if (resolver.code.length == 0) {
            revert UnreachableName(name);
