            ERC165Checker.supportsERC165InterfaceUnchecked(
                resolver,
                type(IExtendedResolver).interfaceId
            );
        if (
            ERC165Checker.supportsERC165InterfaceUnchecked(
                resolver,
                type(IERC7996).interfaceId
            ) &&
            (!multi ||
                (extended &&
                    IERC7996(resolver).supportsFeature(
                        ResolverFeatures.RESOLVE_MULTICALL
                    )))
        ) {
