                    resolver,
                    data,
                    this.resolveDirectImmediateCallback.selector, // ==> step 2
                    IDENTITY_FUNCTION,
                    ""
                );
            }
        }
        bytes[] memory calls;
        if (multi) {
            calls = abi.decode(
                BytesUtils.substring(data, 4, data.length - 4),
                (bytes[])
            );
        } else {
            calls = new bytes[](1);
            calls[0] = data;
        }
        if (extended) {
            for (uint256 i; i < calls.length; ++i) {
                calls[i] = _makeExtendedCall(
                    extendedDNS,
                    name,
                    calls[i],
                    context
                );
            }
        }
        ccipRead(
            address(this),
            abi.encodeCall(
                this.ccipBatch,
                (createBatch(resolver, calls, batchGateways))
