// SPDX-License-Identifier: MIT
pragma solidity 0.8.25;

import {IGatewayProvider} from "@ens/contracts/ccipRead/IGatewayProvider.sol";
import {ENS} from "@ens/contracts/registry/ENS.sol";
import {ReverseClaimer} from "@ens/contracts/reverseRegistrar/ReverseClaimer.sol";
import {RegistryUtils} from "@ens/contracts/universalResolver/RegistryUtils.sol";

import {AbstractNormalizedUniversalResolver} from "./AbstractNormalizedUniversalResolver.sol";

/// @notice Universal Resolver for ENSv1.
contract UniversalResolverV1 is AbstractNormalizedUniversalResolver, ReverseClaimer {
    ////////////////////////////////////////////////////////////////////////
    // Immutables
    ////////////////////////////////////////////////////////////////////////

    /// @notice ENSv1 global registry.
    ENS public immutable REGISTRY_V1;

    ////////////////////////////////////////////////////////////////////////
    // Initialization
    ////////////////////////////////////////////////////////////////////////

    /// @param namer The primary name owner.
    /// @param ens ENSv1 global registry.
    /// @param _batchGatewayProvider Shared batch gateway provider.
    constructor(address namer, ENS ens, IGatewayProvider _batchGatewayProvider)
        AbstractNormalizedUniversalResolver(_batchGatewayProvider)
        ReverseClaimer(ens, namer)
    {
        REGISTRY_V1 = ens;
    }

    ////////////////////////////////////////////////////////////////////////
    // Implementation
    ////////////////////////////////////////////////////////////////////////

    /// @notice Same as `REGISTRY_V1()` for backwards-compatability with ENSv1.
    function registry() external view returns (ENS) {
        return REGISTRY_V1;
    }

    /// @inheritdoc AbstractNormalizedUniversalResolver
    function findResolver(bytes memory name)
        public
        view
        override
        returns (address, bytes32, uint256)
    {
        // https://docs.ens.domains/ensip/10       
        return RegistryUtils.findResolver(REGISTRY_V1, name, 0);
    }

    /// @inheritdoc AbstractNormalizedUniversalResolver
    function isENSv2() public pure override returns (bool) {
        return false;
    }
}

// SPDX-License-Identifier: MIT
pragma solidity 0.8.25;

import {IGatewayProvider} from "@ens/contracts/ccipRead/IGatewayProvider.sol";

import {IPermissionedRegistry} from "../registry/interfaces/IPermissionedRegistry.sol";
import {IContractNamer} from "../reverse-registrar/interfaces/IContractNamer.sol";
import {DelegatedContractNamer} from "../utils/DelegatedContractNamer.sol";

import {AbstractNormalizedUniversalResolver} from "./AbstractNormalizedUniversalResolver.sol";
import {LibResolution} from "./libraries/LibResolution.sol";

/// @notice Universal Resolver for ENSv2.
contract UniversalResolverV2 is AbstractNormalizedUniversalResolver, DelegatedContractNamer {
    ////////////////////////////////////////////////////////////////////////
    // Immutables
    ////////////////////////////////////////////////////////////////////////

    /// @notice ENSv2 root registry.
    IPermissionedRegistry public immutable ROOT_REGISTRY;

    ////////////////////////////////////////////////////////////////////////
    // Initialization
    ////////////////////////////////////////////////////////////////////////

    /// @param rootRegistry ENSv2 root registry.
    /// @param batchGatewayProvider Shared batch gateway provider.
    /// @param contractNamer Delegated contract namer.
    constructor(
        IPermissionedRegistry rootRegistry,
        IGatewayProvider batchGatewayProvider,
        IContractNamer contractNamer
    )
        AbstractNormalizedUniversalResolver(batchGatewayProvider)
        DelegatedContractNamer(contractNamer)
    {
        ROOT_REGISTRY = rootRegistry;
    }

    /// @inheritdoc AbstractNormalizedUniversalResolver
    function supportsInterface(bytes4 interfaceId)
        public
        view
        virtual
        override(AbstractNormalizedUniversalResolver, DelegatedContractNamer)
        returns (bool)
    {
        return super.supportsInterface(interfaceId);
    }

    ////////////////////////////////////////////////////////////////////////
    // Implementation
    ////////////////////////////////////////////////////////////////////////

    /// @inheritdoc AbstractNormalizedUniversalResolver
    function findResolver(bytes memory name)
        public
        view
        override
        returns (address resolver, bytes32 node, uint256 offset)
    {
        (, resolver, node, offset) = LibResolution.findUnvalidatedResolver(ROOT_REGISTRY, name, 0);
    }

    /// @inheritdoc AbstractNormalizedUniversalResolver
    function isENSv2() public pure override returns (bool) {
        return true;
    }
}

project/src/utils/DelegatedContractNamer.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.13;

import {ERC165} from "@openzeppelin/contracts/utils/introspection/ERC165.sol";

import {IContractNamer} from "../reverse-registrar/interfaces/IContractNamer.sol";

/// @dev Mixin for delegated contract naming. 
abstract contract DelegatedContractNamer is ERC165, IContractNamer {
    ////////////////////////////////////////////////////////////////////////
    // Immutables
    ////////////////////////////////////////////////////////////////////////

    /// @notice Delegated contract namer.
    IContractNamer public immutable CONTRACT_NAMER;

    ////////////////////////////////////////////////////////////////////////
    // Initialization
    ////////////////////////////////////////////////////////////////////////

    /// @param contractNamer Delegated contract namer.
    constructor(IContractNamer contractNamer) {
        CONTRACT_NAMER = contractNamer;
    }

    /// @inheritdoc ERC165
    function supportsInterface(bytes4 interfaceId) public view virtual override returns (bool) {
        return
            interfaceId == type(IContractNamer).interfaceId || super.supportsInterface(interfaceId);
    }

    ////////////////////////////////////////////////////////////////////////
    // Implementation
    ////////////////////////////////////////////////////////////////////////

    /// @inheritdoc IContractNamer
    function isContractNamer(address namer) external view returns (bool) {
        return CONTRACT_NAMER.isContractNamer(namer);
    }
}

